mapper.sql:
fi.org_id = #{query.orgId}

    AND fi.user_id = #{query.userId}


    AND fi.user_id = #{query.startUserId}


    AND (fd.name LIKE CONCAT('%', #{query.keyword}, '%')
    OR fd.code LIKE CONCAT('%', #{query.keyword}, '%')

        OR fi.id = #{query.keywordInstanceId}

    )


    AND fi.category = #{query.category}


    AND fi.current_node_name LIKE CONCAT('%', #{query.currentNodeName}, '%')


    AND fi.status = #{query.status}


    AND fi.start_time >= #{query.startTimeBegin}


    AND fi.start_time <= #{query.startTimeEnd}

mapper.select:
SELECT fi.id AS instance_id, MIN(ft.start_time) AS start_time FROM flow_instance fi INNER JOIN flow_task ft ON ft.instance_id = fi.id AND ft.org_id = fi.org_id AND ft.node_key = fi.current_node_key WHERE fi.org_id = #{orgId} AND fi.id IN
#{instanceId}
GROUP BY fi.id
